import { ArrowRight, CheckCircle2 } from "lucide-react";
import { SERVICE_WORKFLOWS, type ServiceWorkflow } from "@/lib/services/workflows";
export default function ServiceJourney({type}:{type:string}){const workflow=SERVICE_WORKFLOWS[type as ServiceWorkflow];if(!workflow)return null;return <section className="rounded-2xl border border-sky-200 bg-sky-50 p-5" aria-label="How this service works"><p className="text-[10px] font-bold uppercase tracking-widest text-sky-700">Your customer’s journey</p><h3 className="mt-2 text-lg font-bold text-[#174766]">{workflow.name}</h3><p className="mt-1 text-xs leading-5 text-slate-600">{workflow.examples}</p><ol className="my-4 grid gap-3 sm:grid-cols-2">{workflow.steps.map((step,i)=><li key={step} className="flex items-start gap-2 text-xs leading-5 text-slate-700"><span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-[#174766] text-[10px] font-bold text-white">{i+1}</span>{step}</li>)}</ol><p className="flex items-start gap-2 border-t border-sky-200 pt-3 text-xs leading-6 text-[#174766]"><CheckCircle2 className="mt-1 size-4 shrink-0"/>{workflow.setup}</p></section>;}
